import Foundation

public enum ForeignSchedulePinsError: Error, Equatable, Sendable {
    case invalid
}

/// The pins of the full foreign timetables (`binario_gtfs_foreign_packs_v1.json`, the same bytes as
/// Android's `gtfs/foreign_packs.json`), generated by the tools with the bundled timetables.
///
/// The bundled index of a pinned pack (`borderOnly`) holds only its border zone: trips touching a
/// station within the pin's radius of an Italian station, and catalogue identities only at its zone
/// stations. Its full timetable is a per-country index published once, never edited, as a GitHub
/// pre-release; the pin names it by tag, URL, size and SHA-256, and the app downloads it only after
/// a tap. A pack without a pin (`borderOnly` false, no artifact) is bundled whole as before and is
/// never offered.
///
/// Every rule of the generator is checked again here (tag, URL prefix, digests, sizes, schema of
/// the index, zone within the served stations): a file that breaks one is ignored as a whole, and
/// the app behaves as without it.
public struct ForeignSchedulePins: Equatable, Sendable {
    public static let resourceName = "binario_gtfs_foreign_packs_v1"
    public static let resourceExtension = "json"
    public static let schemaVersion = 1
    public static let repository = "fz1101hub/binario"
    /// Every artifact URL starts with this prefix: the releases of the project's own repository.
    public static let releaseDownloadPrefix = "https://github.com/fz1101hub/binario/releases/download/"
    /// The host of `releaseDownloadPrefix`, the only one asked first.
    public static let releaseHost = "github.com"
    /// The hosts GitHub redirects a release download to; no other redirect is followed.
    public static let githubReleaseDownloadHost = "release-assets.githubusercontent.com"
    public static let githubLegacyReleaseDownloadHost = "objects.githubusercontent.com"
    /// The tag of an iPhone artifact: this prefix, the source, a dash and the first 12 hex of its SHA-256.
    public static let iosTagPrefix = "gtfs-ios-"
    static let maximumBytes = 1_048_576
    static let maximumPacks = 16
    static let maximumStations = 8_192
    static let maximumIdentifierLength = 64

    /// The radius of the first border rule (pins written before 23 Nov 2026); nil for the corridor rule
    /// (`frontalieri-corridors-v1`), whose zone is only the stations listed in `zoneStationIDs`.
    public let radiusKm: Double?
    public let packs: [Pack]

    /// One foreign pack: which catalogue stations its full timetable serves, which of them its
    /// bundled border zone already serves completely, and its iPhone artifact when it is pinned.
    public struct Pack: Equatable, Sendable {
        public let sourceID: String
        /// ISO 3166-1 alpha-2, «CH», «AT», «FR».
        public let country: String
        /// The last service day of the pinned timetable, yyyymmdd.
        public let lastServiceDay: Int
        public let servedStationIDs: Set<String>
        public let zoneStationIDs: Set<String>
        /// True when the bundled pack is the border subset of the full one.
        public let borderOnly: Bool
        public let ios: Artifact?

        /// The full timetable can be downloaded: the bundled pack is its border subset and the
        /// iPhone artifact is pinned.
        public var isDownloadable: Bool { borderOnly && ios != nil }

        /// A station the full timetable serves outside the border zone: while it is not installed,
        /// its trains in this pack are incomplete or missing.
        public func needsFullTimetable(_ stationID: String) -> Bool {
            servedStationIDs.contains(stationID) && !zoneStationIDs.contains(stationID)
        }

        /// The pinned timetable ended before `day` (yyyymmdd): it is not offered any more.
        public func hasEnded(before day: Int) -> Bool {
            lastServiceDay < day
        }

        /// Noon in Rome of the last service day, for display in any time zone.
        public var lastServiceDate: Date {
            ForeignSchedulePins.date(fromDay: lastServiceDay) ?? Date(timeIntervalSince1970: 0)
        }
    }

    /// The pinned iPhone artifact: a zlib-compressed SQLite index in the schema of the bundled one.
    public struct Artifact: Equatable, Sendable {
        public let tag: String
        public let asset: String
        public let url: URL
        /// The size of the compressed file, the most the download may receive.
        public let sizeBytes: Int
        public let sha256: String
        public let databaseSHA256: String
        public let databaseSizeBytes: Int
        public let inputFingerprintSHA256: String

        /// The first 12 hex of the artifact's SHA-256, as in its tag and in the installed file's name.
        public var shortDigest: String { String(sha256.prefix(12)) }
    }

    public init(data: Data) throws {
        guard data.count <= Self.maximumBytes else { throw ForeignSchedulePinsError.invalid }
        let file: File
        do {
            file = try JSONDecoder().decode(File.self, from: data)
        } catch {
            throw ForeignSchedulePinsError.invalid
        }
        guard file.schemaVersion == Self.schemaVersion,
              file.repository == Self.repository,
              file.borderZone.radiusKm.map({ $0 > 0 && $0 <= 200 }) ?? true,
              !file.packs.isEmpty, file.packs.count <= Self.maximumPacks
        else { throw ForeignSchedulePinsError.invalid }
        var packs: [Pack] = []
        var seen = Set<String>()
        for entry in file.packs {
            let pack = try Self.validated(entry)
            guard seen.insert(pack.sourceID).inserted else { throw ForeignSchedulePinsError.invalid }
            packs.append(pack)
        }
        radiusKm = file.borderZone.radiusKm
        self.packs = packs
    }

    /// The pins of the app's bundle, or nil when the file is absent, too large or breaks a rule.
    public static func load(url: URL?) -> ForeignSchedulePins? {
        guard let url, url.isFileURL,
              let size = try? url.resourceValues(forKeys: [.fileSizeKey]).fileSize,
              size > 0, size <= maximumBytes,
              let data = try? Data(contentsOf: url),
              data.count == size
        else { return nil }
        return try? ForeignSchedulePins(data: data)
    }

    public func pack(_ sourceID: String) -> Pack? {
        packs.first { $0.sourceID == sourceID }
    }

    /// The packs whose full timetable can be downloaded, in the order of the file.
    public var downloadablePacks: [Pack] {
        packs.filter(\.isDownloadable)
    }

    /// The Rome calendar day of `date` as yyyymmdd: the day a pin's last service day is compared with.
    public static func romeDay(_ date: Date) -> Int {
        let parts = romeCalendar.dateComponents([.year, .month, .day], from: date)
        let year: Int = parts.year ?? 0
        let month: Int = parts.month ?? 0
        let day: Int = parts.day ?? 0
        return year * 10_000 + month * 100 + day
    }

    static func date(fromDay day: Int) -> Date? {
        var components = DateComponents()
        components.year = day / 10_000
        components.month = day / 100 % 100
        components.day = day % 100
        components.hour = 12
        return romeCalendar.date(from: components)
    }

    private static let romeCalendar: Calendar = {
        var calendar = Calendar(identifier: .gregorian)
        calendar.locale = Locale(identifier: "en_US_POSIX")
        calendar.timeZone = TimeZone(identifier: "Europe/Rome") ?? TimeZone(secondsFromGMT: 3_600) ?? .current
        return calendar
    }()

    private static func validated(_ entry: File.PackEntry) throws -> Pack {
        guard isIdentifier(entry.sourceId),
              entry.country.utf8.count == 2, entry.country.utf8.allSatisfy({ (65...90).contains($0) }),
              let lastServiceDay = day(entry.lastServiceDate),
              day(entry.fullServiceUntil) != nil,
              entry.servedStationIds.count <= maximumStations,
              entry.zoneStationIds.count <= maximumStations
        else { throw ForeignSchedulePinsError.invalid }
        let served = Set(entry.servedStationIds)
        let zone = Set(entry.zoneStationIds)
        guard served.count == entry.servedStationIds.count, zone.count == entry.zoneStationIds.count,
              served.allSatisfy(isStationIdentifier), zone.isSubset(of: served)
        else { throw ForeignSchedulePinsError.invalid }
        // D2: a pack is reduced to its border zone exactly when it is pinned.
        guard entry.borderOnly == (entry.ios != nil) else { throw ForeignSchedulePinsError.invalid }
        var artifact: Artifact?
        if let ios = entry.ios {
            artifact = try validated(ios, sourceID: entry.sourceId)
        }
        return Pack(
            sourceID: entry.sourceId,
            country: entry.country,
            lastServiceDay: lastServiceDay,
            servedStationIDs: served,
            zoneStationIDs: zone,
            borderOnly: entry.borderOnly,
            ios: artifact
        )
    }

    private static func validated(_ ios: File.IOS, sourceID: String) throws -> Artifact {
        let expectedTag = iosTagPrefix + sourceID + "-" + String(ios.sha256.prefix(12))
        let expectedURL = releaseDownloadPrefix + expectedTag + "/" + ios.asset
        guard SHA256Digest.isHex(ios.sha256),
              ios.tag == expectedTag,
              isAsset(ios.asset),
              ios.url == expectedURL,
              let url = URL(string: ios.url),
              let components = URLComponents(url: url, resolvingAgainstBaseURL: false),
              components.scheme == "https", components.host == releaseHost, components.port == nil,
              components.user == nil, components.password == nil, components.query == nil, components.fragment == nil,
              (1...BundledGTFSScheduleInstaller.maximumCompressedBytes).contains(ios.sizeBytes),
              SHA256Digest.isHex(ios.database.sha256),
              (1...BundledGTFSScheduleInstaller.maximumDatabaseBytes).contains(ios.database.sizeBytes),
              ios.database.userVersion == Int(SQLiteGTFSJourneyRepository.userVersion),
              ios.database.applicationId == Int(SQLiteGTFSJourneyRepository.applicationID),
              SHA256Digest.isHex(ios.inputFingerprintSha256)
        else { throw ForeignSchedulePinsError.invalid }
        return Artifact(
            tag: ios.tag,
            asset: ios.asset,
            url: url,
            sizeBytes: ios.sizeBytes,
            sha256: ios.sha256,
            databaseSHA256: ios.database.sha256,
            databaseSizeBytes: ios.database.sizeBytes,
            inputFingerprintSHA256: ios.inputFingerprintSha256
        )
    }

    /// A source identifier: lower-case ASCII letters, digits and dashes, as `ch-otd-gtfs`.
    private static func isIdentifier(_ value: String) -> Bool {
        let bytes = Array(value.utf8)
        guard let first = bytes.first, bytes.count <= maximumIdentifierLength,
              (97...122).contains(first) || (48...57).contains(first) else { return false }
        return bytes.allSatisfy { (97...122).contains($0) || (48...57).contains($0) || $0 == 45 }
    }

    /// A catalogue identifier: printable ASCII without spaces or quotes, at most 64 characters.
    private static func isStationIdentifier(_ value: String) -> Bool {
        let bytes = Array(value.utf8)
        return !bytes.isEmpty && bytes.count <= maximumIdentifierLength
            && bytes.allSatisfy { $0 > 32 && $0 < 127 && $0 != 34 && $0 != 92 }
    }

    /// A release asset name: ASCII letters, digits, «.», «_» and «-», never «..».
    private static func isAsset(_ value: String) -> Bool {
        let bytes = Array(value.utf8)
        guard !bytes.isEmpty, bytes.count <= 128, !value.contains(".."), bytes.first != 46 else { return false }
        return bytes.allSatisfy { byte in
            (97...122).contains(byte) || (65...90).contains(byte) || (48...57).contains(byte)
                || byte == 46 || byte == 95 || byte == 45
        }
    }

    /// «2026-12-12» as 20261212, for a real calendar day only.
    private static func day(_ value: String) -> Int? {
        let parts = value.split(separator: "-", omittingEmptySubsequences: false)
        guard parts.count == 3, parts[0].count == 4, parts[1].count == 2, parts[2].count == 2,
              let year = Int(parts[0]), let month = Int(parts[1]), let day = Int(parts[2]),
              (2000...2999).contains(year), (1...12).contains(month), (1...31).contains(day)
        else { return nil }
        let encoded = year * 10_000 + month * 100 + day
        guard let date = date(fromDay: encoded), romeDay(date) == encoded else { return nil }
        return encoded
    }

    private struct File: Decodable {
        let schemaVersion: Int
        let repository: String
        let borderZone: BorderZone
        let packs: [PackEntry]

        struct BorderZone: Decodable {
            let radiusKm: Double?
        }

        struct PackEntry: Decodable {
            let sourceId: String
            let country: String
            let lastServiceDate: String
            let fullServiceUntil: String
            let servedStationIds: [String]
            let zoneStationIds: [String]
            let borderOnly: Bool
            let ios: IOS?
        }

        struct IOS: Decodable {
            let tag: String
            let asset: String
            let url: String
            let sizeBytes: Int
            let sha256: String
            let database: Database
            let inputFingerprintSha256: String
        }

        struct Database: Decodable {
            let sha256: String
            let sizeBytes: Int
            let userVersion: Int
            let applicationId: Int
        }
    }
}
